window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"R86D521hq3s","speaker":"Lord Fakafanua","role":"Prime Minister","country":"Tonga","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=R86D521hq3s","date":"20260925","title":"🇹🇴 Tonga - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1106,"words":2046,"counts":{"claims":37,"promises":8,"attacks":0},"topics":[{"topic":"Climate action","share":0.1264,"seconds":140},{"topic":"Pacific climate funding","share":0.0659,"seconds":73},{"topic":"Tonga digital sovereignty","share":0.0655,"seconds":72},{"topic":"Pacific ocean peace","share":0.0642,"seconds":71},{"topic":"Tonga climate vulnerability","share":0.0634,"seconds":70},{"topic":"Tonga ocean strategy","share":0.0623,"seconds":69},{"topic":"UN Security Council reform","share":0.0622,"seconds":69},{"topic":"Tonga security","share":0.0597,"seconds":66},{"topic":"Tonga sovereignty","share":0.0586,"seconds":65},{"topic":"Pacific climate","share":0.0582,"seconds":64},{"topic":"Tonga renewable energy","share":0.058,"seconds":64},{"topic":"Tonga independence","share":0.0563,"seconds":62},{"topic":"Tonga greetings","share":0.0563,"seconds":62},{"topic":"UN reform","share":0.0558,"seconds":62},{"topic":"Tonga energy security","share":0.0555,"seconds":61},{"topic":"UN multilateralism","share":0.0318,"seconds":35}],"timeline":[[1,63,"Tonga greetings"],[65,127,"Tonga independence"],[129,194,"Tonga sovereignty"],[194,256,"UN reform"],[258,327,"UN Security Council reform"],[329,400,"Pacific ocean peace"],[402,468,"Tonga security"],[470,534,"Pacific climate"],[535,608,"Pacific climate funding"],[610,677,"Climate action"],[679,749,"Tonga climate vulnerability"],[751,820,"Tonga ocean strategy"],[821,883,"Tonga energy security"],[885,949,"Tonga renewable energy"],[951,1023,"Tonga digital sovereignty"],[1025,1098,"Climate action"],[1098,1133,"UN multilateralism"]],"stances":{"Tonga greetings":"Lord Fakafanua delivers warm greetings on behalf of the King and people of Tonga while noting his nine months in office.","Tonga independence":"Lord Fakafanua asserts that Tonga has a long history of preserving its sovereignty and rights through indigenous leadership and constitutional measures.","Tonga sovereignty":"Lord Fakafanua asserts that Tonga's sovereignty allows it to project ideas rather than might and demands equal treatment under the UN Charter.","UN reform":"Lord Fakafanua argues that the United Nations must transform to reflect current realities and better serve developing nations.","UN Security Council reform":"Lord Fakafanua calls for a more inclusive UN Security Council that recognizes the triple planetary crisis and advocates for equitable financing and representation.","Pacific ocean peace":"Lord Fakafanua states that the Pacific region has declared itself an ocean of peace to prevent military escalation and emphasizes that this concept extends beyond merely the absence of conflict.","Tonga security":"Lord Fakafanua states that Tonga faces pressing threats including transnational crime and nuclear contamination, and affirms the country's commitment to using technology and partnerships to address these challenges while protecting marginalized groups.","Pacific climate":"Lord Fakafanua states that the Pacific is facing an immediate climate crisis, emphasizes the critical importance of staying below 1.5 degrees Celsius, and highlights the economic losses caused by natural disasters while advocating for early warning systems.","Pacific climate funding":"Lord Fakafanua states that current financing for Pacific resilience and weather preparedness is insufficient and calls on partners to invest in Pacific-owned solutions.","Climate action":"Lord Fakafanua asserts that climate action is a legal obligation requiring difficult decisions, highlights the breach of planetary boundaries, and calls for the phase-out of fossil fuel subsidies and recognition of vulnerability indices.","Tonga climate vulnerability":"Lord Fakafanua states that Tonga is among the world's most vulnerable countries due to climate change and calls for global action on sea level rise.","Tonga ocean strategy":"Lord Fakafanua states that Tonga is committed to protecting 30% of its ocean by 2030 and plans to convene a Polynesian Ocean Summit in 2027.","Tonga energy security":"Lord Fakafanua argues that Tonga must reduce reliance on imported fossil fuels to ensure energy security and climate resilience.","Tonga renewable energy":"Lord Fakafanua states that Tonga aims for 70% renewable energy by 2030 and 100% by 2035, while emphasizing the need to address digital connectivity and infrastructure inequalities.","Tonga digital sovereignty":"Lord Fakafanua asserts that Tonga must exercise sovereignty over its data and natural assets while shaping global technological rules rather than merely enduring transformations.","UN multilateralism":"Lord Fakafanua asserts that Tonga supports an international rules-based order founded on the UN Charter and equality of nations, emphasizing the need to preserve the multilateral system."},"claims":[{"t":50,"quote":"Nine months into my service as prime minister","topic":"Tonga greetings","kind":"number"},{"t":108,"quote":"Under King George I, Tonga preserved its independence during an era of colonial","topic":"Tonga independence","kind":"fact"},{"t":116,"quote":"Our Constitution of 1875 secured Towin's rights and freedoms over seven decades before the Universal Declaration of Human Rights.","topic":"Tonga independence","kind":"fact"},{"t":129,"quote":"It reflects our fierce determination to chart our own course. That is the essence of our sovereignty.","topic":"Tonga sovereignty","kind":"fact"},{"t":140,"quote":"allows us to project the power of our ideas rather than the might of our","topic":"Tonga sovereignty","kind":"fact"},{"t":196,"quote":"too much of our international architecture still reflects the world of 1945 rather than today's realities","topic":"UN reform","kind":"fact"},{"t":227,"quote":"developing countries who are too often excluded from both","topic":"UN reform","kind":"fact"},{"t":269,"quote":"We need a more inclusive security council equipped for today's challenges. A security council that recognizes the triple planetary crisis as a profound threat to peace and security.","topic":"UN Security Council reform","kind":"fact"},{"t":306,"quote":"Tong has nominated Ambassador Ivon Baky of Ecuador, whose vision for a renewed reformed United Nations speaks to the needs of vulnerable states.","topic":"UN Security Council reform","kind":"fact"},{"t":333,"quote":"the Pacific region spans onethird of the Earth's surface","topic":"Pacific ocean peace","kind":"fact"},{"t":379,"quote":"we have declared our region an ocean of peace in 2025","topic":"Pacific ocean peace","kind":"fact"},{"t":402,"quote":"Our most pressing threats already reaching our shores. Transnational crime, illicit drugs, illegal, unregulated, and unreported fishing.","topic":"Tonga security","kind":"fact"},{"t":413,"quote":"Cyber threats and unresolved consequences of nuclear testing and radioactive contamination remain.","topic":"Tonga security","kind":"fact"},{"t":445,"quote":"This year, Tonga ratified United Nations Convention on Rights of Persons with reaffirming our commitment to the dignity and the equal participation of persons with disabilities.","topic":"Tonga security","kind":"fact"},{"t":460,"quote":"We also aceded to the treaty on the non-prololiferation of nuclear weapons and ratified the comprehensive nuclear testban treaty.","topic":"Tonga security","kind":"fact"},{"t":470,"quote":"In doing so, we completed the universal universalization of the CTBT in the Pacific.","topic":"Pacific climate","kind":"fact"},{"t":488,"quote":"UNEP's limiting overshoot report warns that exceeding 1.5 degrees Celsius could occur within the next few years.","topic":"Pacific climate","kind":"fact"},{"t":517,"quote":"The Pacific loses an estimated of $500 million every year due to natural disasters such as cyclones, flooding.","topic":"Pacific climate","kind":"number"},{"t":551,"quote":"The Pacific Resiliency Facility, our own financing mechanism for building community resilience, needs a further 328 million in pledges to reach its initial capitalization target of $500","topic":"Pacific climate funding","kind":"number"},{"t":567,"quote":"Weather Ready Pacific, designed to reduce the human and economic costs of severe weather events, needs a further 160 million to reach its target.","topic":"Pacific climate funding","kind":"number"},{"t":577,"quote":"Tonga's climate trust fund, a direct community fund, which dispersed its first round of grants this year, also requires significant funding support.","topic":"Pacific climate funding","kind":"fact"},{"t":626,"quote":"Seven of the nine planetary boundaries have been breached by human activity.","topic":"Climate action","kind":"fact"},{"t":654,"quote":"We must phase out the explicit fossil fuel subsidies estimated by the IMF at 725 billion.","topic":"Climate action","kind":"number"},{"t":679,"quote":"By any credible index, Tong is amongst the world's most vulnerable countries.","topic":"Tonga climate vulnerability","kind":"fact"},{"t":717,"quote":"It marks the first time all member states have agreed on a single common text on sea level rise.","topic":"Tonga climate vulnerability","kind":"fact"},{"t":732,"quote":"Over the last few years, Tonga has endured cyclones, flooding, earthquakes, and tsunamis.","topic":"Tonga climate vulnerability","kind":"fact"},{"t":759,"quote":"Tong has committed to protecting at least 30% of our ocean by 2030.","topic":"Tonga ocean strategy","kind":"number"},{"t":765,"quote":"Our ratification of the BB&amp;J agreement extends that commitment beyond our waters, supporting the protection of marine biodiversity on the high seas.","topic":"Tonga ocean strategy","kind":"fact"},{"t":871,"quote":"When we import fossil fuels, we also import their volatility.","topic":"Tonga energy security","kind":"fact"},{"t":889,"quote":"70% renewable energy by 2030, 100% renewable energy by 2035.","topic":"Tonga renewable energy","kind":"number"},{"t":941,"quote":"For Tonga, submarine cables and satellite links are foundational infrastructures that connect our islands to global opportunities.","topic":"Tonga renewable energy","kind":"fact"},{"t":951,"quote":"But connectivity alone is not enough. Digital skills and secure, resilient systems must support it.","topic":"Tonga digital sovereignty","kind":"fact"},{"t":966,"quote":"Tonga does not need to be first in artificial intelligence, quantum computing, or every technology that follows.","topic":"Tonga digital sovereignty","kind":"fact"},{"t":1045,"quote":"Meet the 1.5° C threshold.","topic":"Climate action","kind":"fact"},{"t":1060,"quote":"recognize the imbalance between the funds we commit to addressing our collective development challenges and those we are prepared to spend on","topic":"Climate action","kind":"fact"},{"t":1098,"quote":"Tonga believes in an international rules-based order founded on the UN charter and equality of nations.","topic":"UN multilateralism","kind":"fact"},{"t":1108,"quote":"And that is the multilateral system we must preserve.","topic":"UN multilateralism","kind":"fact"}],"promises":[{"t":420,"quote":"In this respect, our region is committed to directly utilizing innovative technologies and working closely with our trusted security partners to address our security challenges.","topic":"Tonga security","kind":"promise"},{"t":435,"quote":"We are committed to protecting the rights of marginalized people and ending violence against women and young girls.","topic":"Tonga security","kind":"promise"},{"t":788,"quote":"It is in that spirit that we intend to convene a Polynesian Ocean Summit in Tonga May of 2027 to move from shared ambition to practical action.","topic":"Tonga ocean strategy","kind":"promise"},{"t":960,"quote":"And we will protect our children online and retain sovereignty over our national data.","topic":"Tonga digital sovereignty","kind":"promise"},{"t":979,"quote":"It will exercise sovereignty by helping shape the rules and norms around it.","topic":"Tonga digital sovereignty","kind":"promise"},{"t":990,"quote":"We are seeking to unlock new forms of finance through responsible valuation of our natural assets, our ocean assets while exploring the potential of frontier technologies such as quantum","topic":"Tonga digital sovereignty","kind":"promise"},{"t":1005,"quote":"We will form the right partnerships. We will direct innovation towards our priorities.","topic":"Tonga digital sovereignty","kind":"promise"},{"t":1040,"quote":"We will do our part.","topic":"Climate action","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Tonga greetings","text":"The assembly will hear an address by his Lord Faka, Prime Minister of the Kingdom of Tonga. I request protocol to escort his excellency and invite him to address the Mr. President, the general assembly, your excellencies, ladies and gentlemen, I bring you warm greetings from His Majesty King Dubo V 6 and the people of the Kingdom of Tonga. Nine months into my service as prime minister, I stand here mindful that Pacific leaders have come before me, raising the same warnings, making the same appeals."},{"t":65,"topic":"Tonga independence","text":"Today, I'm compelled to make them again. The question before us is not whether the world has heard our message, but why has it still not acted? We live in a world more connected than ever, but greater connection has not bought greater unity. We meet amid deepening division, geopolitical conflict, and competition. For Tonga, navigating such stormy currents is not new. As descendants of voyages, we have been in the survival business much longer than most have Under King George I, Tonga preserved its independence during an era of colonial Our Constitution of 1875 secured Towin's rights and freedoms over seven decades before the Universal Declaration of Human Rights."},{"t":129,"topic":"Tonga sovereignty","text":"It reflects our fierce determination to chart our own course. That is the essence of our sovereignty. allows us to project the power of our ideas rather than the might of our Tonga participates as an equal under the founding principles of the United Nations Charter, the sovereign equality of states. This is how we must approach our theme. Restoring trust, managing a united nation that delivers for all. Enduring trust is restored when commitments produce results. True transformation is realized when our communities, economies, and ecosystems can anticipate change and recover with greater strength. The small line developing states must not bear the disproportionate costs of the challenges they did little to Mr."},{"t":194,"topic":"UN reform","text":"President, too much of our international architecture still reflects the world of 1945 rather than today's realities. If the United Nations is to remain the principal vehicle through which sovereign nations confront global challenges, it must transform. We need a United Nations that enables One that expands meaningful access to investment and technology, especially for the islands, developing countries who are too often excluded from both. We need a stronger general assembly and institutions that respond effectively to the needs of the majority of our We cannot keep negotiating climate, biodiversity, and the ocean and separate cops when they are clearly an interconnected ecosystem requiring integrated and coherent solutions."},{"t":258,"topic":"UN Security Council reform","text":"We call on global processes to recognize the ocean climate nexus and address these interconnected challenges We need a more inclusive security council equipped for today's challenges. A security council that recognizes the triple planetary crisis as a profound threat to peace and security. We need a financial architecture that delivers timely and accessible financing to those who most need them. pledge commitments must be actioned The next secretary general must understand these realities intimately. It is in this spirit that Tong has nominated Ambassador Ivon Baky of Ecuador, whose vision for a renewed reformed United Nations speaks to the needs of vulnerable states. To restore trust, every member state, large or small, must have a voice in shaping this organization's future and a stake in its success."},{"t":329,"topic":"Pacific ocean peace","text":"Mr. President, your excellencies, the Pacific region spans onethird of the Earth's surface. It is our home. Through the 2050 strategy for the blue Pacific continent, we have set our own course and identified our thematic priorities. For Tonga, investing in the ocean and nature is foundational in achieving its development ambition. Protecting and restoring them builds our climate resilience. It strengthens our food security and enables a sta sustainable blue economy. The financing and partnerships we build around ocean and nature-based solutions will help determine our future and sustain our people. Mr. President, we have declared our region an ocean of peace in 2025. It sends a clear message. The Pacific must not become a staging ground for military escalation or a battleground for major power However, our ocean of peace is more than the absence of conflict."},{"t":402,"topic":"Tonga security","text":"Our most pressing threats already reaching our shores. Transnational crime, illicit drugs, illegal, unregulated, and unreported fishing. Cyber threats and unresolved consequences of nuclear testing and radioactive contamination remain. In this respect, our region is committed to directly utilizing innovative technologies and working closely with our trusted security partners to address our security challenges. We are committed to protecting the rights of marginalized people and ending violence against women and young girls. This year, Tonga ratified United Nations Convention on Rights of Persons with reaffirming our commitment to the dignity and the equal participation of persons with disabilities. We also aceded to the treaty on the non-prololiferation of nuclear weapons and ratified the comprehensive nuclear testban treaty."},{"t":470,"topic":"Pacific climate","text":"In doing so, we completed the universal universalization of the CTBT in the Pacific. On climate, the Pacific is already drowning in a crisis, a crisis that others continue to postpone addressing. UNEP's limiting overshoot report warns that exceeding 1.5 degrees Celsius could occur within the next few years. But crossing that threshold must not become an excuse for abandoning it. We must peak as low as possible and return below 1.5 degrees Celsius as quickly as Every fraction of a degree matters. The Pacific loses an estimated of $500 million every year due to natural disasters such as cyclones, flooding. Early warning systems give communities time to prepare and reduce these losses."},{"t":535,"topic":"Pacific climate funding","text":"That may be a modest sum in global terms, but for Pacific nations, it is a heavy toll on our countries and our people. And yet the financing to prevent such losses still falls short. The Pacific Resiliency Facility, our own financing mechanism for building community resilience, needs a further 328 million in pledges to reach its initial capitalization target of $500 Weather Ready Pacific, designed to reduce the human and economic costs of severe weather events, needs a further 160 million to reach its target. Tonga's climate trust fund, a direct community fund, which dispersed its first round of grants this year, also requires significant funding support. We call on all all our partners to invest in these Pacific designed and Pacific owned solutions. Tonga stands behind 2,26 Pacific Island foreign leaders, the Balau declaration, and calls on all our major emitters to act urgently."},{"t":610,"topic":"Climate action","text":"Climate action is a legal obligation, but meeting those obligations will require difficult decisions rooted in Climate leadership is not a popularity Seven of the nine planetary boundaries have been breached by human activity. Climate action is not an option. Tonga is accelerating its transition away from fossil fuels and expanding renewable energy. And we encourage the shift to electric vehicles. For us, decarbonizing also means greater energy security and protection from global for fuel price We must phase out the explicit fossil fuel subsidies estimated by the IMF at 725 billion. International financial institutions and multilateral development banks must recognize the multi-dimensional vulnerability index, the MVI, which ensures that it informs eligibility and allocations."},{"t":679,"topic":"Tonga climate vulnerability","text":"By any credible index, Tong is amongst the world's most vulnerable countries. However, we call on all nations, especially the world's largest emitters, to attend the pre-OP 31 meetings in Fiji and Touvalu in October this year. Come to the Pacific and confront what 1.5 degrees means for our water, our people, our food, our homes, and our We welcome the general assembly's declaration on sea level rise, a significant achievement for the preservation of sovereignty. It marks the first time all member states have agreed on a single common text on sea level rise. Our resilience account for every hazard, including geohhazards confronting our Over the last few years, Tonga has endured cyclones, flooding, earthquakes, and tsunamis. This year, the super El Nino currently forming over the Pacific Ocean further intensifies weather patterns, compounding the pressures on our people."},{"t":751,"topic":"Tonga ocean strategy","text":"We therefore need integrated warning and response systems that can protect our communities against the full range of planetary risks. Tong has committed to protecting at least 30% of our ocean by 2030. Our ratification of the BB&amp;J agreement extends that commitment beyond our waters, supporting the protection of marine biodiversity on the high seas. Our task is to navigate a course that safeguards the ocean and unlocks its value to our people. This principle underpins Tonga's ocean strategy. It is in that spirit that we intend to convene a Polynesian Ocean Summit in Tonga May of 2027 to move from shared ambition to practical action. But our responsibility does not stop at the boundaries of our Pacific continent. Consider the humpback whales. Born in Tonga's warm oceans, it migrates to Antarctica to feed on krill before returning to the Pacific to escape the winter and breed."},{"t":821,"topic":"Tonga energy security","text":"Tonga's sanctuary protects them, but their survival depends on healthy ecosystems at both ends of that journey. What happens in the southern seas of Antarctica is felt in the southern oceans of Tonga. So we invite partners to join us in Tonga with practical commitments that recognize the scale and interconnectedness of our shared ocean Mr. President, the same principle extends across our development. Interconnection must not be for Tonga. Resilience means taking greater control of the forces shaping our future and turning the resources within our geography into greater When we import fossil fuels, we also import their volatility. Moving away from them is therefore both a climate imperative and an energy security necessity."},{"t":885,"topic":"Tonga renewable energy","text":"Tonga is not short of ambition. 70% renewable energy by 2030, 100% renewable energy by 2035. However, the forces shaping our future are not solely environmental or economic. They're increasingly Mr. President, digital connectivity and rapid technology advancements are transforming how we live. They offer significant opportunities for big ocean sovereign states. boss, but they also risk creating new inequalities and dependencies. Those who benefit last from global change often bear its highest costs. We continue to live with that injustice through climate change. We cannot again be asked to adapt only after systems have been built and the rules written. For Tonga, submarine cables and satellite links are foundational infrastructures that connect our islands to global opportunities."},{"t":951,"topic":"Tonga digital sovereignty","text":"But connectivity alone is not enough. Digital skills and secure, resilient systems must support it. And we will protect our children online and retain sovereignty over our national data. Tonga does not need to be first in artificial intelligence, quantum computing, or every technology that follows. But Tonga will not simply endure global transformations. It will exercise sovereignty by helping shape the rules and norms around it. Tonga is looking beyond conventional development models. We are seeking to unlock new forms of finance through responsible valuation of our natural assets, our ocean assets while exploring the potential of frontier technologies such as quantum We will form the right partnerships. We will direct innovation towards our priorities. But the Pacific's data ocean, biodiversity, critical minerals, and traditional knowledge must not power the next technological revolution while returning only a fraction of their value to our people."},{"t":1025,"topic":"Climate action","text":"Mr. President, from experience, Tonga knows its challenges and we will meet them with determination that has always defined our people. We also know our strengths as a boss. We are not asking for charity. We will do our part. We will simply ask that others do theirs. Meet the 1.5° C threshold. Help us protect the planet we all share and the ocean that connects us. Ensure that everyone benefit benefits from technological advancements. recognize the imbalance between the funds we commit to addressing our collective development challenges and those we are prepared to spend on Let's uphold the rules and institutions that allow every nation to participate as an equal sovereign. That is the promise at the heart of the United Nations. Not that all nations would be equal in power, but that no nation, however powerful, is more sovereign than That is the multilateral system."},{"t":1098,"topic":"UN multilateralism","text":"Tonga believes in an international rules-based order founded on the UN charter and equality of nations. And that is the multilateral system we must preserve. Mr. President, I so submit. God bless us all. Maloito, on behalf of the assembly, I wish to thank uh the prime minister of the Kingdom of Tonga. And now"}],"compare":[{"topic":"Tonga","share":0.2392,"mean":0.0,"rank":1,"others":0},{"topic":"Climate Change","share":0.1846,"mean":0.0421,"rank":8,"others":77},{"topic":"UN & its reform","share":0.1498,"mean":0.205,"rank":119,"others":170},{"topic":"Latin America","share":0.0659,"mean":0.0044,"rank":6,"others":12},{"topic":"Indo-Pacific","share":0.0642,"mean":0.0038,"rank":5,"others":6}]};
